// 永信旅人小鎮：作息、地點與事件（地圖右半是永信街區；左半不使用）
export const SLOT_STARTS = [7, 9, 12, 13, 16, 18, 22]; // 各時段開始的小鎮時刻
export const SLOT_LABELS = ['07:00–09:00', '09:00–12:00', '12:00–13:00', '13:00–16:00', '16:00–18:00', '18:00–22:00', '22:00 之後'];
// 小鎮時鐘：現實 1 秒 = 小鎮 1 分鐘，一天約 24 分鐘
export function townMinutes(now: number) {
  return Math.floor(now / 1000) % 1440;
}
export function townClock(now: number) {
  const m = townMinutes(now);
  return `${String(Math.floor(m / 60)).padStart(2, '0')}:${String(m % 60).padStart(2, '0')}`;
}
export function slotIndex(now: number) {
  const h = Math.floor(townMinutes(now) / 60);
  let idx = 6;
  for (let i = 0; i < SLOT_STARTS.length; i++) if (h >= SLOT_STARTS[i]) idx = i;
  if (h < 7) idx = 6;
  return idx;
}
