// ===== 花蓮支線：區域、火車、離場 =====
export type Region = 'daxue' | 'hualien' | 'train';
export const REGION_NAMES: Record<string, string> = { daxue: '（未使用）', hualien: '永信街區', train: '移動中' };
export const STATION_OF: Record<string, string> = { daxue: 'station', hualien: 'hl_station' };
export const REGION_CENTER: Record<string, { x: number; y: number }> = { daxue: { x: 20, y: 20 }, hualien: { x: 60, y: 20 } };
export const TRAIN_MINUTES = 150; // 車程：小鎮 2.5 小時＝現實 150 秒
export const HUALIEN_X = 40; // x >= 40 是花蓮
// 搭車中的角色暫放在地圖最上排（牆上，畫面會隱藏）
export function trainSeat(seat: number) {
  return { x: 2 + (seat % 30), y: 0 };
}
export function regionOf(pos: { x: number; y: number }): Region {
  if (pos.y < 1) return 'train';
  return pos.x >= HUALIEN_X ? 'hualien' : 'daxue';
}
export function locRegion(loc: string): Region {
  return loc.startsWith('hl_') ? 'hualien' : 'daxue';
}
// 作息表上空白的時段＝離場（回家、收攤），畫面隱藏、AI 暫停
export const RECENT_MARK = '【最近發生的事】';
// plan 裡還有「最近發生的事」＝事件進行中，不會離場（例：子安 22:00 後還在花蓮聚會）
export function isOffstage(name: string | undefined, now: number, plan?: string) {
  if (!name) return false;
  if (plan && plan.includes(RECENT_MARK)) return false;
  const s = SCHEDULES[name];
  return !!s && s[slotIndex(now)] === '';
}
export function nearSpots(loc: string, pos: { x: number; y: number }, dist = 1) {
  return (LOCATION_SPOTS[loc] ?? []).some(
    (s) => Math.abs(s[0] - Math.floor(pos.x)) + Math.abs(s[1] - Math.floor(pos.y)) <= dist,
  );
}

// ===== 火車班次：每 30 分鐘一班，首班 06:00、末班 23:00 =====
export const FIRST_TRAIN = 6 * 60;
export const LAST_TRAIN = 23 * 60;
export function nextDeparture(now: number) {
  const tm = now / 1000; // 小鎮分鐘（含小數）
  const dayStart = Math.floor(tm / 1440) * 1440;
  let m = Math.ceil((tm - dayStart) / 30) * 30;
  if (m < FIRST_TRAIN) m = FIRST_TRAIN;
  if (m > LAST_TRAIN) m = 1440 + FIRST_TRAIN;
  return (dayStart + m) * 1000;
}
// 小鎮天數：從世界建立那天算第 1 天，第 1 天是週一
const WEEKDAYS = ['一', '二', '三', '四', '五', '六', '日'];
export function townDay(now: number, worldCreated: number) {
  const d = Math.floor(now / 1440000) - Math.floor(worldCreated / 1440000) + 1;
  return { day: d, weekday: WEEKDAYS[(d - 1) % 7], weekend: (d - 1) % 7 >= 5 };
}
export const NOTE_MINUTES = 180; // 「最近發生的事」在事件結束（hold 到期）3 小時後淡忘

// ===== 約定：對話裡說要去哪裡，聊完就照做 =====
// 每個地點的常見說法（含模型常編的不存在地點，對應到最接近的真實地點）
export const PLACE_ALIASES: Record<string, string[]> = {
  hl_station: ['永信門市', '門市', '永信', '旅行社', '店裡'],
  hl_music: ['講座', '書店', '說明會'],
  hl_ee: ['辦公大樓', '公司', '辦公室', '上班的地方'],
  hl_dorm: ['咖啡廳', '咖啡店', '喝咖啡'],
  hl_night: ['旅展', '攤位', '展場'],
  hl_sea: ['海濱公園', '公園', '海邊', '散步'],
};
const PLAN_INTENT = /(去|來|過去|過來|見|等你|找你|碰面|集合|會合|約在|一起去|陪你)/;
const PLAN_NEGATIVE = /(改天|下次|有空再|不去|不要去|不用來|算了|以後再)/;

// 由最後一句往前找，回傳約定的地點 id；在花蓮的人說「宿舍」「車站」時對應到花蓮那一個
export function detectPlan(texts: string[], region: Region): string | null {
  for (const t of [...texts].reverse()) {
    if (!PLAN_INTENT.test(t) || PLAN_NEGATIVE.test(t)) continue;
    let best: { loc: string; len: number } | null = null;
    for (const [loc, names] of Object.entries(PLACE_ALIASES)) {
      for (const n of names) {
        if (t.includes(n) && (!best || n.length > best.len)) best = { loc, len: n.length };
      }
    }
    if (!best) continue;
    let loc = best.loc;
    if (region === 'hualien' && loc === 'dorm') loc = 'hl_dorm';
    if (region === 'hualien' && loc === 'station') loc = 'hl_station';
    return loc;
  }
  return null;
}

export const PLACES_PROMPT =
  '這是一條有永信旅遊門市的街區。可以去的地方只有：永信旅遊門市、歐洲旅遊講座・書店、辦公大樓、咖啡廳、旅展攤位、海濱公園。約見面時請說出其中一個地點，不要提到其他不存在的地方。';

// ===== 和玩家聊天 =====
export const HUMAN_TALK_DISTANCE = 5; // 有玩家的對話，相距 5 格內就能開聊
// 婉拒（不呼叫模型，立刻回應）
export function declineLine(where?: string) {
  const lines = where
    ? [`抱歉，我要趕去${where}，晚點再聊！`, `我現在要去${where}，等一下再找你喔！`]
    : ['抱歉，我現在有點事，等一下再聊！', '我手上有事在忙，晚點找你好嗎？'];
  return lines[Math.floor(Math.random() * lines.length)];
}
// 插話時，原本在聊的人先離開
export function goodbyeLine() {
  const lines = ['你們聊，我先走囉！', '那我先去忙了，你們慢慢聊～', '剛好我也要走了，掰掰！'];
  return lines[Math.floor(Math.random() * lines.length)];
}
